// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address actor, address caller) public {
        vm.assume(actor != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != actor);
        amount = bound(amount, 1, 1e30);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        vm.prank(caller);
        uint256 reported = c.getBalance(actor);
        assertTrue(reported == amount);
    }
}
